function makeCallbacksVar() {
  const fns = [];
  for (var i = 0; i < 3; i++) {
    fns.push(() => i);
  }
  return fns;
}

function makeCallbacksLet() {
  const fns = [];
  for (let i = 0; i < 3; i++) {
    fns.push(() => i);
  }
  return fns;
}

console.log(makeCallbacksVar().map(fn => fn()));
console.log(makeCallbacksLet().map(fn => fn()));
